package mz.bam.seeky.android;

import android.app.*;import android.content.*;import android.content.pm.*;import android.database.*;import android.net.Uri;import android.os.*;import android.provider.*;import android.speech.tts.*;import java.io.*;import java.nio.file.Files;import java.util.*;import java.util.concurrent.TimeUnit;import java.util.zip.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class)
@Config(manifest=Config.NONE,sdk=33,application=Application.class,shadows={ChapterExportTest.WavTts.class})
@LooperMode(LooperMode.Mode.PAUSED)
public class ChapterExportTest {
 static File root,epub,sourceOverride;static int chunks;static boolean fail,cancelWrite,longOutput;static int failAfter=-1;static NarrationExportService service;static final List<String> voiceTexts=new ArrayList<>();
 @Implements(TextToSpeech.class) public static class WavTts extends ShadowTextToSpeech {
  @Implementation protected int synthesizeToFile(CharSequence text,Bundle args,File file,String id){if(fail||failAfter>=0&&chunks>=failAfter){getUtteranceProgressListener().onError(id);return TextToSpeech.SUCCESS;}try{voiceTexts.add(text.toString());byte[] data=new byte[longOutput?1920:2];int value=++chunks;for(int n=0;n<data.length;n+=2)data[n]=(byte)value;VoiceToolsTest.writeWav(file,data);getUtteranceProgressListener().onDone(id);return TextToSpeech.SUCCESS;}catch(IOException e){return TextToSpeech.ERROR;}}
 }
 public static class Destination extends DocumentsProvider {
  public boolean onCreate(){return true;}
  File file(String id){return new File(root,id);}
  public Cursor queryRoots(String[] projection){return new MatrixCursor(new String[]{"root_id","document_id"});}
  public Cursor queryDocument(String id,String[] projection){MatrixCursor c=new MatrixCursor(new String[]{"document_id","_display_name","mime_type","flags"});File f=file(id);c.addRow(new Object[]{id,f.getName(),f.isDirectory()?DocumentsContract.Document.MIME_TYPE_DIR:"audio/wav",0});return c;}
  public Cursor queryChildDocuments(String id,String[] projection,String sort){return new MatrixCursor(new String[]{"document_id"});}
  public ParcelFileDescriptor openDocument(String id,String mode,CancellationSignal signal)throws FileNotFoundException{if(cancelWrite&&!mode.equals("r"))service.cancelled=true;return ParcelFileDescriptor.open(file(id),mode.equals("r")?ParcelFileDescriptor.MODE_READ_ONLY:ParcelFileDescriptor.MODE_CREATE|ParcelFileDescriptor.MODE_TRUNCATE|ParcelFileDescriptor.MODE_WRITE_ONLY);}
  public String createDocument(String parent,String mime,String name)throws FileNotFoundException{String id=parent+"/"+name;File f=file(id);try{if(mime.equals(DocumentsContract.Document.MIME_TYPE_DIR))f.mkdirs();else if(!f.createNewFile())throw new IOException();return id;}catch(IOException e){throw new FileNotFoundException();}}
  public boolean isChildDocument(String parent,String child){return child.startsWith(parent+"/");}
  public void deleteDocument(String id){file(id).delete();}
 }
 public static class Source extends ContentProvider {public boolean onCreate(){return true;}public String getType(Uri uri){return "application/epub+zip";}public ParcelFileDescriptor openFile(Uri uri,String mode)throws FileNotFoundException{return ParcelFileDescriptor.open(sourceOverride==null?epub:sourceOverride,ParcelFileDescriptor.MODE_READ_ONLY);}public Cursor query(Uri u,String[] p,String s,String[] a,String o){return null;}public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){return 0;}public int delete(Uri u,String s,String[] a){return 0;}}
 ServiceController<NarrationExportService> controller;
 @Before public void setup()throws Exception{Application app=RuntimeEnvironment.getApplication();root=Files.createTempDirectory("narration-destination-").toFile();new File(root,"root").mkdirs();epub=new File(app.getCacheDir(),"book.epub");chunks=0;voiceTexts.clear();sourceOverride=null;fail=cancelWrite=longOutput=false;failAfter=-1;try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(epub))){entry(zip,"META-INF/container.xml","<container><rootfiles><rootfile full-path='book.opf'/></rootfiles></container>");entry(zip,"book.opf","<package><metadata xmlns:dc='http://purl.org/dc/elements/1.1/'><dc:title>Estudos de Ciências</dc:title><dc:creator>Ana Silva</dc:creator></metadata><manifest><item id='a' href='a.html' media-type='application/xhtml+xml'/><item id='b' href='b.html' media-type='application/xhtml+xml'/></manifest><spine><itemref idref='a'/><itemref idref='b'/></spine></package>");entry(zip,"a.html","<html><body><h1>Introdução</h1><p>Primeiro capítulo completo.</p></body></html>");entry(zip,"b.html","<html><body><h2>Energia e movimento</h2><p>Segundo capítulo completo.</p></body></html>");}register(app,"seeky.chapter.source",new Source(),false);register(app,"seeky.chapter.dest",new Destination(),true);ShadowTextToSpeech.addVoice(new Voice("pt-natural",new Locale("pt","PT"),500,200,true,Collections.emptySet()));controller=Robolectric.buildService(NarrationExportService.class).create();service=controller.get();}
 static void entry(ZipOutputStream zip,String name,String text)throws IOException{zip.putNextEntry(new ZipEntry(name));zip.write(text.getBytes("UTF-8"));zip.closeEntry();}
 static void register(Application app,String authority,ContentProvider provider,boolean documents){ProviderInfo info=new ProviderInfo();info.authority=authority;if(documents){info.exported=true;info.grantUriPermissions=true;info.readPermission=info.writePermission="android.permission.MANAGE_DOCUMENTS";}provider.attachInfo(app,info);ShadowContentResolver.registerProviderInternal(authority,provider);}
 Intent request(int first,int last){return new Intent().setAction(NarrationExportService.START).setDataAndType(Uri.parse("content://seeky.chapter.source/book"),"application/epub+zip").putExtra("name","Livro.epub").putExtra("engine","com.google.android.tts").putExtra("voice","pt-natural").putExtra("language","pt").putExtra("online",true).putExtra("rate",1f).putExtra("first",first).putExtra("last",last).putExtra("tree",DocumentsContract.buildTreeDocumentUri("seeky.chapter.dest","root").toString());}
 void finish()throws Exception{for(int i=0;i<1000&&service.busy;i++){shadowOf(Looper.getMainLooper()).idle();TextToSpeech tts=ShadowTextToSpeech.getLastTextToSpeechInstance();if(tts!=null&&shadowOf(tts).getUtteranceProgressListener()==null)shadowOf(tts).getOnInitListener().onInit(TextToSpeech.SUCCESS);Thread.sleep(10);}service.worker.submit(()->{}).get(10,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();assertFalse(service.busy);System.out.println("Batch result: "+shadowOf(service.getSystemService(NotificationManager.class)).getNotification(NarrationExportService.ID).extras.getCharSequence(Notification.EXTRA_BIG_TEXT));}
 @After public void close(){controller.destroy();}
 @Test public void wholeBookProducesOneWavPerChapterWithOriginalSamples()throws Exception{service.onStartCommand(request(0,1),0,1);finish();assertEquals(2,service.saved);List<File> output=wavFiles();assertEquals(2,output.size());for(File file:output){int part=file.getName().endsWith("0001.wav")?1:2;byte[] bytes=Files.readAllBytes(file.toPath());assertArrayEquals(new byte[]{(byte)((part-1)*2+1),0},Arrays.copyOfRange(bytes,44,46));Map<String,String> tags=tags(file);assertEquals("Estudos de Ciências",tags.get("IPRD"));assertEquals("Ana Silva",tags.get("IART"));assertEquals(""+part,tags.get("ITRK"));assertTrue(tags.get("INAM").contains(part==1?"Introdução":"Energia e movimento"));assertTrue(file.getName().startsWith("Estudos de Ciências — "));}assertTrue(new File(service.cache,"job.json").isFile());}
 @Test public void chapterRangeSavesOnlyRequestedChapter()throws Exception{service.onStartCommand(request(1,1),0,1);finish();assertEquals(1,service.saved);assertTrue(wavFiles().get(0).getName().equals("Estudos de Ciências — Energia e movimento — 0002.wav"));}
 @Test public void failedSynthesisLeavesNoPublishedPartialAudio()throws Exception{fail=true;service.onStartCommand(request(0,1),0,1);finish();assertEquals(0,service.saved);assertTrue(wavFiles().isEmpty());assertTrue(new File(service.cache,"job.json").isFile());}
 @Test public void cancelDuringDestinationCopyDeletesOnlyItsPartialFile()throws Exception{cancelWrite=true;File existing=new File(root,"root/preserved.wav");Files.write(existing.toPath(),new byte[]{9});service.onStartCommand(request(0,1),0,1);finish();assertEquals(0,service.saved);assertEquals(1,wavFiles().size());assertTrue(existing.exists());assertTrue(new File(service.cache,"job.json").isFile());}
 @Test public void aFailedLaterChapterResumesWithoutRepeatingCompletedChapters()throws Exception{failAfter=2;service.onStartCommand(request(0,1),0,1);finish();assertEquals(1,service.saved);String jobId=service.job.id();assertEquals(1,service.job.i("part"));controller.destroy();controller=Robolectric.buildService(NarrationExportService.class).create();service=controller.get();failAfter=-1;service.onStartCommand(new Intent().setAction(NarrationExportService.START).putExtra("resume_job",jobId),0,2);finish();assertEquals(2,service.saved);assertEquals(4,chunks);assertEquals(2,wavFiles().size());assertEquals("complete",service.job.s("status"));}
 @Test public void aSingleLargeOutputJoinsChaptersAndRetainsItsTitle()throws Exception{service.onStartCommand(request(0,1).putExtra("single",true),0,1);finish();assertEquals(1,service.saved);File file=wavFiles().get(0);assertEquals(192008,WaveJoiner.inspect(file).length);byte[] bytes=Files.readAllBytes(file.toPath());assertSpeechMarkers(file,4);assertTrue(tags(file).get("INAM").contains("Livro inteiro"));}
 @Test public void aDocumentWithoutChapterStructureCanBeSaved()throws Exception{Intent intent=request(0,0).putExtra("selection","Um documento inteiro sem capítulos, preparado para narração.").putExtra("single",true);service.onStartCommand(intent,0,1);finish();assertEquals(1,service.saved);assertEquals(1,wavFiles().size());}
 @Test public void resumeInsideOneChapterKeepsAlreadySynthesisedChunks()throws Exception{try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(epub))){entry(zip,"META-INF/container.xml","<container><rootfiles><rootfile full-path='book.opf'/></rootfiles></container>");entry(zip,"book.opf","<package><manifest><item id='a' href='a.html' media-type='application/xhtml+xml'/></manifest><spine><itemref idref='a'/></spine></package>");StringBuilder text=new StringBuilder("<html><body><h1>Uma leitura longa</h1>");for(int i=0;i<250;i++)text.append("<p>Uma frase para construir um capítulo longo sem perder as pausas.</p>");text.append("</body></html>");entry(zip,"a.html",text.toString());}failAfter=1;service.onStartCommand(request(0,0).putExtra("single",true),0,1);finish();assertTrue(service.job.i("offset")>0);assertEquals(96002,service.job.n("bytes"));String jobId=service.job.id();controller.destroy();epub.delete();controller=Robolectric.buildService(NarrationExportService.class).create();service=controller.get();failAfter=-1;service.onStartCommand(new Intent().setAction(NarrationExportService.START).putExtra("resume_job",jobId),0,2);finish();assertEquals(1,service.saved);File output=wavFiles().get(0);WaveJoiner.Format format=WaveJoiner.inspect(output);byte[] bytes=Files.readAllBytes(output.toPath());assertEquals(chunks*2+96000,format.length);assertSpeechMarkers(output,chunks);}
 @Test public void readyAudioCanBeSavedAfterTheOriginalDocumentWasRemoved()throws Exception{cancelWrite=true;service.onStartCommand(request(0,0),0,1);finish();assertTrue(service.job.b("ready"));String id=service.job.id();controller.destroy();epub.delete();cancelWrite=false;controller=Robolectric.buildService(NarrationExportService.class).create();service=controller.get();service.onStartCommand(new Intent().setAction(NarrationExportService.START).putExtra("resume_job",id),0,2);finish();assertEquals(1,service.saved);assertEquals(2,chunks);assertEquals(1,wavFiles().size());}
 @Test public void generatedAudioCanIncludeBackgroundAtItsIndependentVolume()throws Exception{Application app=RuntimeEnvironment.getApplication();File musicRoot=new File(app.getFilesDir(),"backgrounds");musicRoot.mkdirs();File music=new File(musicRoot,"fixture.audio");byte[] musicData=new byte[48000];for(int n=0;n<musicData.length;n+=2){musicData[n]=(byte)0xe8;musicData[n+1]=3;}VoiceToolsTest.writeWav(music,musicData);Intent intent=request(0,0).putExtra("selection","Uma pequena narração para a mistura de fundo.").putExtra("background",music.getPath()).putExtra("background_volume",100);NarrationJob job=NarrationJob.create(app,intent);longOutput=true;service.onStartCommand(new Intent().setAction(NarrationExportService.START).putExtra("resume_job",job.id()),0,1);finish();assertEquals(1,service.saved);byte[] pcm=Files.readAllBytes(wavFiles().get(0).toPath());int at=44+1000;assertEquals(1001,(short)((pcm[at]&255)|(pcm[at+1]<<8)));}
 @Test public void anActualTextBookWithoutChaptersUsesWholeDocumentExport()throws Exception{sourceOverride=new File(RuntimeEnvironment.getApplication().getCacheDir(),"no-chapters.txt");StringBuilder text=new StringBuilder("Um livro sem capítulos\n\n");for(int i=0;i<1200;i++)text.append("Uma frase de estudo para uma leitura longa, com as suas pausas.\n");Files.write(sourceOverride.toPath(),text.toString().getBytes("UTF-8"));service.onStartCommand(request(0,0).setDataAndType(Uri.parse("content://seeky.chapter.source/book"),"text/plain").putExtra("name","no-chapters.txt").putExtra("single",true),0,1);finish();assertEquals(1,service.saved);assertTrue(chunks>20);assertEquals(chunks*2+96000,WaveJoiner.inspect(wavFiles().get(0)).length);}
 @Test public void savedPauseHasExactlyTwoSecondsAndBackgroundContinuesDuringIt()throws Exception{Application app=RuntimeEnvironment.getApplication();File dir=new File(app.getFilesDir(),"backgrounds");dir.mkdirs();File music=new File(dir,"pause.audio");byte[] data=new byte[48000];for(int i=0;i<data.length;i+=2){data[i]=(byte)0xe8;data[i+1]=3;}VoiceToolsTest.writeWav(music,data);longOutput=true;service.onStartCommand(request(0,0).putExtra("selection","Título isolado\n\nUm conteúdo com ponto final.").putExtra("background",music.getPath()).putExtra("background_volume",100),0,1);finish();File out=wavFiles().get(0);WaveJoiner.Format fmt=WaveJoiner.inspect(out);assertEquals(99840,fmt.length);byte[] pcm=Files.readAllBytes(out.toPath());int at=44+1920+48000;assertEquals(1000,(short)((pcm[at]&255)|(pcm[at+1]<<8)));}
 @Test public void preExistingNarrationJobKeepsItsLegacyLayoutOnResume()throws Exception{NarrationJob old=NarrationJob.create(RuntimeEnvironment.getApplication(),request(0,1).putExtra("single",true));old.put("speech_layout_version",0);old.save();service.onStartCommand(new Intent().setAction(NarrationExportService.START).putExtra("resume_job",old.id()),0,1);finish();assertEquals(1,service.saved);assertEquals(4,WaveJoiner.inspect(wavFiles().get(0)).length);assertEquals(2,chunks);}
 @Test public void bibleReferencesAreExpandedOnlyAtSynthesisAndKeepSourceHash()throws Exception{String text="Leia Isaías 5:6, depois confirme João 3:16.";service.onStartCommand(request(0,0).putExtra("selection",text).putExtra("single",true),0,1);finish();assertEquals(1,service.saved);assertEquals(Collections.singletonList("Leia Isaías capítulo 5, versículo 6, depois confirme João capítulo 3, versículo 16."),voiceTexts);assertEquals(VoiceIdentity.key("narration",SpeechText.prepare(text).text),service.job.s("text_hash"));assertEquals(1,wavFiles().size());}
 @Test public void existingCheckpointWithBibleReferencesResumesWithoutRestarting()throws Exception{String text="Título isolado\n\nLeia Isaías 5:6, depois confirme João 3:16.";failAfter=1;service.onStartCommand(request(0,0).putExtra("selection",text).putExtra("single",true),0,1);finish();assertEquals(1,chunks);assertEquals(96002,service.job.n("bytes"));String id=service.job.id(),hash=service.job.s("text_hash");assertEquals(VoiceIdentity.key("narration",SpeechText.prepare(text).text),hash);assertTrue(service.job.i("offset")>0);controller.destroy();controller=Robolectric.buildService(NarrationExportService.class).create();service=controller.get();failAfter=-1;service.onStartCommand(new Intent().setAction(NarrationExportService.START).putExtra("resume_job",id),0,2);finish();assertEquals(2,chunks);assertEquals(hash,service.job.s("text_hash"));assertEquals(Arrays.asList("Título isolado","Leia Isaías capítulo 5, versículo 6, depois confirme João capítulo 3, versículo 16."),voiceTexts);assertEquals(1,service.saved);assertEquals(96004,WaveJoiner.inspect(wavFiles().get(0)).length);}
 @Test public void singleWavRetainsEmbeddedChapterIndexAfterDatabaseEntryIsRemoved()throws Exception{service.onStartCommand(request(0,1).putExtra("single",true),0,1);finish();File file=wavFiles().get(0);List<WavCues.Cue> cues;try(InputStream in=new FileInputStream(file)){cues=WavCues.read(in);}assertEquals(2,cues.size());assertEquals("Introdução",cues.get(0).label);assertEquals("Energia e movimento",cues.get(1).label);assertEquals(0,cues.get(0).milliseconds);assertTrue(cues.get(1).milliseconds>=2000);try(PlusStore db=new PlusStore(service)){db.getWritableDatabase().delete("audio_cues",null,null);db.getWritableDatabase().delete("audio_tracks",null,null);}List<WavCues.Cue> fallback=NarrationIndex.load(service,Uri.fromFile(file));assertEquals(2,fallback.size());assertEquals(cues.get(1).milliseconds,fallback.get(1).milliseconds);assertSpeechMarkers(file,4);}
 @Test public void pausedExportUsesItsOriginalPronunciationRulesAfterDictionaryChanges()throws Exception{PlusUi.saveRule(service,"",new PronunciationRules.Rule("Seeky","Siqui"));String text="Seeky\n\nUma frase sobre Seeky.";failAfter=1;service.onStartCommand(request(0,0).putExtra("selection",text).putExtra("single",true),0,1);finish();assertEquals(Collections.singletonList("Siqui"),voiceTexts);String id=service.job.id();controller.destroy();PlusUi.saveRule(RuntimeEnvironment.getApplication(),"Seeky",new PronunciationRules.Rule("Seeky","Outro nome"));controller=Robolectric.buildService(NarrationExportService.class).create();service=controller.get();failAfter=-1;service.onStartCommand(new Intent().setAction(NarrationExportService.START).putExtra("resume_job",id),0,2);finish();assertEquals(Arrays.asList("Siqui","Uma frase sobre Siqui."),voiceTexts);assertEquals(1,service.saved);assertEquals(96004,WaveJoiner.inspect(wavFiles().get(0)).length);}
 static void assertSpeechMarkers(File file,int count)throws IOException{WaveJoiner.Format f=WaveJoiner.inspect(file);int mark=1;try(RandomAccessFile in=new RandomAccessFile(file,"r")){in.seek(f.offset);for(long at=0;at<f.length;at+=2){int lo=in.readUnsignedByte(),hi=in.readUnsignedByte();if(lo==0&&hi==0)continue;assertEquals(0,hi);assertEquals(mark++&255,lo);}}assertEquals(count+1,mark);}
 static Map<String,String> tags(File file)throws IOException{Map<String,String> tags=new HashMap<>();try(RandomAccessFile in=new RandomAccessFile(file,"r")){in.seek(12);while(in.getFilePointer()+8<=in.length()){int id=in.readInt();long size=Integer.toUnsignedLong(Integer.reverseBytes(in.readInt())),start=in.getFilePointer(),end=start+size;if(end>in.length())throw new IOException("Invalid chunk");if(id==0x4c495354&&size>=4&&in.readInt()==0x494e464f){while(in.getFilePointer()+8<=end){byte[] key=new byte[4];in.readFully(key);int count=Integer.reverseBytes(in.readInt());if(count<1||count>2048||in.getFilePointer()+count>end)throw new IOException("Invalid tag");byte[] value=new byte[count];in.readFully(value);tags.put(new String(key,"US-ASCII"),new String(value,0,count-1,"UTF-8"));if((count&1)!=0)in.skipBytes(1);}}in.seek(end+(size&1));}}return tags;}
 List<File> wavFiles()throws IOException{List<File> found=new ArrayList<>();try(java.util.stream.Stream<java.nio.file.Path> all=Files.walk(root.toPath())){all.filter(p->p.toString().endsWith(".wav")).forEach(p->found.add(p.toFile()));}return found;}
}
